-- ============================================================
--  SHOP ANALYTICS DATABASE  (MySQL 8.0+)
--  Synthetic e-commerce data, Jan 2023 - Dec 2024
--  Run the whole file: File > Open SQL Script > lightning bolt
-- ============================================================
DROP DATABASE IF EXISTS shop_analytics;
CREATE DATABASE shop_analytics;
USE shop_analytics;

CREATE TABLE customers (
    customer_id INT PRIMARY KEY,
    first_name  VARCHAR(50),
    last_name   VARCHAR(50),
    email       VARCHAR(100),
    phone       VARCHAR(15),
    city        VARCHAR(50),
    state       VARCHAR(50),
    signup_date DATE
);

CREATE TABLE products (
    product_id   INT PRIMARY KEY,
    product_name VARCHAR(100),
    category     VARCHAR(50),
    price        DECIMAL(10,2),
    cost         DECIMAL(10,2)
);

CREATE TABLE orders (
    order_id       INT PRIMARY KEY,
    customer_id    INT,
    order_date     DATETIME,
    ship_date      DATETIME,
    promised_date  DATETIME,
    delivered_date DATETIME,
    status         VARCHAR(20),
    payment_method VARCHAR(30),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE order_items (
    order_item_id INT PRIMARY KEY,
    order_id      INT,
    product_id    INT,
    quantity      INT,
    unit_price    DECIMAL(10,2),
    discount_pct  INT,
    FOREIGN KEY (order_id)   REFERENCES orders(order_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE reviews (
    review_id   INT PRIMARY KEY,
    order_id    INT,
    rating      TINYINT,
    review_date DATE,
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);






-- Quick check
SELECT 'customers' AS tbl, COUNT(*) AS rows_loaded FROM customers
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'orders', COUNT(*) FROM orders
UNION ALL SELECT 'order_items', COUNT(*) FROM order_items
UNION ALL SELECT 'reviews', COUNT(*) FROM reviews;
